package com.servicerca.security; import com.servicerca.repository.UserRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.http.HttpHeaders;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserRepository users;public JwtAuthenticationFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var h=req.getHeader(HttpHeaders.AUTHORIZATION);if(h!=null&&h.startsWith("Bearer "))try{users.findById(jwt.parseUserId(h.substring(7))).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new SecurityUser(u),null,List.of())));}catch(Exception ignored){}chain.doFilter(req,res);}}
